"use client";

import {
  Children,
  type ButtonHTMLAttributes,
  Fragment,
  isValidElement,
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";
import { CheckIcon, ChevronDownIcon } from "../icons/interface";
import { useDismiss, useFloating, usePresence } from "../interaction/use-floating";
import { cx } from "../utils/cx";

export type SelectOption = { value: string; label: string; disabled?: boolean; description?: string };

export type SelectProps = Omit<
  ButtonHTMLAttributes<HTMLButtonElement>,
  "value" | "defaultValue" | "onChange" | "children"
> & {
  /** The choices, as data. Or pass `<option value="x">Label</option>` children, as with a native select. */
  options?: SelectOption[];
  children?: ReactNode;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Shown when nothing is chosen. */
  placeholder?: string;
  /** Posts the value with a form. */
  name?: string;
};

/** `<option>` children become options, so migrating from a native select is a rename. */
function optionsFrom(children: ReactNode): SelectOption[] {
  const out: SelectOption[] = [];
  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;
    if (child.type === Fragment) {
      out.push(...optionsFrom((child.props as { children?: ReactNode }).children));
      return;
    }
    const props = child.props as { value?: string; disabled?: boolean; children?: ReactNode; label?: string };
    const text =
      props.label ?? (typeof props.children === "string" ? props.children : Children.toArray(props.children).join(""));
    out.push({ value: String(props.value ?? text), label: text, disabled: props.disabled });
  });
  return out;
}

/**
 * A custom single-choice dropdown (not the browser's native menu): the same look, motion and keyboard behavior as the
 * rest of the set. It is the select-only combobox pattern: focus stays on the button while Up and Down move the
 * highlight (`aria-activedescendant`), Enter or Space chooses, Escape closes, and typing jumps to a match. Use
 * `Combobox` when people need to search.
 */
export function Select({
  options: given,
  children,
  value: controlled,
  defaultValue,
  onValueChange,
  placeholder = "Select…",
  name,
  disabled,
  className,
  id,
  onKeyDown,
  ...rest
}: SelectProps) {
  const options = useMemo(() => given ?? optionsFrom(children), [given, children]);
  const [inner, setInner] = useState<string | undefined>(defaultValue ?? undefined);
  const value = controlled === undefined ? inner : controlled;
  const selected = options.find((o) => o.value === value);
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const button = useRef<HTMLButtonElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const typed = useRef({ text: "", at: 0 });
  const auto = useId();
  const listId = `${auto}-list`;
  const optionId = (i: number) => `${auto}-opt-${i}`;

  const { present, state } = usePresence(open, 160);
  useFloating(present, button, list, { side: "bottom", align: "start", offset: 6 });
  const close = useCallback(() => setOpen(false), []);
  const refocus = useCallback(() => button.current?.focus(), []);
  useDismiss(open, button, list, close, refocus);

  const openList = () => {
    const at = options.findIndex((o) => o.value === value && !o.disabled);
    setActive(
      at >= 0
        ? at
        : Math.max(
            0,
            options.findIndex((o) => !o.disabled),
          ),
    );
    setOpen(true);
  };
  const choose = (o: SelectOption | undefined) => {
    if (!o || o.disabled) return;
    if (controlled === undefined) setInner(o.value);
    onValueChange?.(o.value);
    setOpen(false);
    button.current?.focus();
  };
  const move = (dir: 1 | -1, from = active) => {
    for (let n = 1; n <= options.length; n++) {
      const i = (from + dir * n + options.length * n) % options.length;
      if (!options[i]?.disabled) return setActive(i);
    }
  };
  // keep the highlighted option visible
  // biome-ignore lint/correctness/useExhaustiveDependencies: runs when the highlight or open state changes
  useEffect(() => {
    list.current?.querySelector("[data-active]")?.scrollIntoView?.({ block: "nearest" });
  }, [active, present]);

  const key = (e: KeyboardEvent<HTMLButtonElement>) => {
    onKeyDown?.(e);
    if (e.defaultPrevented || disabled) return;
    const printable = e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey && e.key !== " ";
    if (!open) {
      if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key)) {
        e.preventDefault();
        openList();
      } else if (printable) {
        // typing on the closed button picks the next match, like a native select
        const hit = options.findIndex((o) => !o.disabled && o.label.toLowerCase().startsWith(e.key.toLowerCase()));
        if (hit >= 0) choose(options[hit]);
      }
      return;
    }
    if (e.key === "ArrowDown") move(1);
    else if (e.key === "ArrowUp") move(-1);
    else if (e.key === "Home")
      setActive(
        Math.max(
          0,
          options.findIndex((o) => !o.disabled),
        ),
      );
    else if (e.key === "End") setActive(options.length - 1 - [...options].reverse().findIndex((o) => !o.disabled));
    else if (e.key === "Enter" || e.key === " ") choose(options[active]);
    else if (e.key === "Escape") close();
    else if (e.key === "Tab") close();
    else if (printable) {
      const now = e.timeStamp;
      const t = typed.current;
      t.text = now - t.at > 700 ? e.key.toLowerCase() : t.text + e.key.toLowerCase();
      t.at = now;
      const start = t.text.length === 1 ? active + 1 : Math.max(active, 0);
      for (let k = 0; k < options.length; k++) {
        const i = (start + k) % options.length;
        if (!options[i]?.disabled && options[i]?.label.toLowerCase().startsWith(t.text)) {
          setActive(i);
          break;
        }
      }
    } else return;
    e.preventDefault();
  };

  return (
    <div className={cx("hm-select-root", className)}>
      <button
        {...rest}
        ref={button}
        id={id}
        type="button"
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        aria-activedescendant={open ? optionId(active) : undefined}
        disabled={disabled}
        data-placeholder={selected ? undefined : ""}
        className="hm-control hm-select"
        onClick={() => (open ? close() : openList())}
        onKeyDown={key}
      >
        <span className="hm-select-value">{selected?.label ?? placeholder}</span>
        <ChevronDownIcon className="hm-select-chevron" size={14} />
      </button>
      {name ? <input type="hidden" name={name} value={value ?? ""} /> : null}
      {present ? (
        <div
          ref={list}
          id={listId}
          popover="manual"
          role="listbox"
          aria-label={typeof rest["aria-label"] === "string" ? rest["aria-label"] : undefined}
          data-state={state}
          inert={state === "closed" || undefined}
          className="hm-floating hm-menu hm-select-list"
          onPointerDown={(e) => e.preventDefault()}
        >
          {options.map((o, i) => (
            // biome-ignore lint/a11y/useKeyWithClickEvents: keyboard is handled by the combobox button
            <div
              key={o.value}
              id={optionId(i)}
              role="option"
              aria-selected={o.value === value}
              aria-disabled={o.disabled || undefined}
              data-active={i === active ? "" : undefined}
              className="hm-combobox-option"
              onClick={() => choose(o)}
              onPointerMove={() => i !== active && !o.disabled && setActive(i)}
            >
              <span className="hm-combobox-label">{o.label}</span>
              {o.description ? <small className="hm-combobox-description">{o.description}</small> : null}
              <CheckIcon className="hm-combobox-check" size={12} strokeWidth={2} />
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}
